  // src/logger.ts
  var MAX_ITEM_LENGTH = 2e3;
  var MAX_MESSAGE_LENGTH = 300;
  var LEVEL_ORDER = {
    "从不": 0,
    "错误": 1,
    "警告": 2,
    "信息": 3,
    "调试": 4
  };
  var Logger = class {
    static formatItem(item) {
      if (item instanceof Error) {
        return `${item.name}: ${item.message}`;
      }
      if (typeof item === "string") {
        return item.length > MAX_ITEM_LENGTH ? item.slice(0, MAX_ITEM_LENGTH) + `…(+${item.length - MAX_ITEM_LENGTH})` : item;
      }
      try {
        const s2 = JSON.stringify(item);
        if (!s2) return `${item}`;
        return s2.length > MAX_ITEM_LENGTH ? s2.slice(0, MAX_ITEM_LENGTH) + `…(+${s2.length - MAX_ITEM_LENGTH})` : s2;
      } catch (_e) {
        return `${item}`;
      }
    }
    static handleLogData(...data) {
      const { LOG_SHORT_PRINT } = config_default.base;
      let s2 = data.map((item) => this.formatItem(item)).join(" ");
      s2 = s2.replace(/(["']?(?:api[_-]?key|token|authorization|secret|password)["']?\s*[:=]\s*["']?)[^"'\s,}]{6,}/gi, "$1***");
      s2 = s2.replace(/(Bearer\s+)[A-Za-z0-9._-]+/gi, "$1***");
      if (LOG_SHORT_PRINT && s2.length > 1e3) {
        return s2.substring(0, 500) + "\n...\n" + s2.substring(s2.length - 500);
      }
      return s2;
    }
    static emit(level, method, ...data) {
      var _a, _b;
      const { LOG_LEVEL } = config_default.base;
      const current = (_a = LEVEL_ORDER[LOG_LEVEL]) != null ? _a : 3;
      const need = (_b = LEVEL_ORDER[level]) != null ? _b : 3;
      if (current < need) return;
      const s2 = this.handleLogData(...data);
      if (!s2) return;
      console[method](`【${NAME}】[${level}] ${s2}`);
    }
    static debug(...data) {
      this.emit("调试", "info", ...data);
    }
    static info(...data) {
      this.emit("信息", "log", ...data);
    }
    static warning(...data) {
      this.emit("警告", "warn", ...data);
    }
    static error(...data) {
      this.emit("错误", "error", ...data);
    }
    /** 记录异常：消息进 error，堆栈进 debug（调试级别可见） */
    static exception(label, e) {
      const message = e && e.message ? e.message : `${e}`;
      this.error(`${label}: ${message}`);
      if (e && e.stack) this.debug(`${label} 堆栈:
${e.stack}`);
    }
    /** 请求上下文日志：受“日志记录消息内容”开关控制，正文截断，默认不打印 system */
    static printRequestMessages(messages) {
      if (!messages) return;
      const { LOG_MESSAGE_CONTENT } = config_default.base;
      const filtered = messages.filter((item) => item.role !== "system");
      if (filtered.length === 0) return;
      const summary = filtered.map((m2) => {
        const content = typeof m2.content === "string" ? m2.content : JSON.stringify(m2.content || "");
        const toolCalls = m2.tool_calls && m2.tool_calls.length || 0;
        if (!LOG_MESSAGE_CONTENT) {
          return { role: m2.role, length: content.length, toolCalls };
        }
        const truncated = content.length > MAX_MESSAGE_LENGTH ? content.slice(0, MAX_MESSAGE_LENGTH) + `…(+${content.length - MAX_MESSAGE_LENGTH})` : content;
        return { role: m2.role, content: truncated, toolCalls };
      });
      this.info(`请求上下文:
`, JSON.stringify(summary));
    }
    /** 分段打印长文本，避免日志截断丢失内容 */
    static logLong(label, text, chunkSize = 1500) {
      if (!text) return;
      if (text.length <= chunkSize) {
        this.info(label, text);
        return;
      }
      for (let i = 0; i < text.length; i += chunkSize) {
        this.info(`${label}[${i}]:`, text.slice(i, i + chunkSize));
      }
    }
  };
  var logger = Logger;

