  async function forwardSegmentsToText(epId, message) {
    if (typeof message === "string") return message;
    if (!Array.isArray(message)) return "";
    let text = "";
    for (const seg of message) {
      if (!seg || typeof seg !== "object") continue;
      switch (seg.type) {
        case "text":
          text += seg.data && seg.data.text || "";
          break;
        case "at":
          text += `@${seg.data && seg.data.qq || ""} `;
          break;
        case "face":
          text += `[表情${seg.data && seg.data.id || ""}]`;
          break;
        case "image":
          text += "[图片]";
          break;
        case "record":
          text += "【语音】";
          break;
        case "video":
          text += `【视频】${seg.data && (seg.data.file || seg.data.url) || ""}`;
          break;
        case "file":
          text += `【文件】${seg.data && (seg.data.name || seg.data.file || seg.data.file_id) || ""}`;
          break;
        case "json":
          text += parseCardToText(seg.data && seg.data.data);
          break;
        case "music":
          text += parseMusicToText(seg.data || {});
          break;
        case "node": {
          text += await forwardMessagesToText(epId, [seg]);
          break;
        }
        case "forward": {
          const sub = await getForwardMessage(epId, seg.data && seg.data.id || "");
          text += await forwardMessagesToText(epId, sub);
          break;
        }
        default:
          text += `[${seg.type}]`;
      }
    }
    return text;
  }
  async function forwardMessagesToText(epId, messages) {
    const lines = [];
    for (const m2 of messages) {
      if (!m2 || typeof m2 !== "object") continue;
      const nodeData = m2.type === "node" ? m2.data || {} : null;
      const sender = nodeData || m2.sender || {};
      const name = sender.card || sender.nickname || `用户${sender.user_id || ""}`;
      const content = await forwardSegmentsToText(epId, nodeData ? nodeData.content : m2.message);
      lines.push(`${name}: ${content}`);
    }
    return lines.join("\n");
  }
