  function getPathMapConfig(key) {
    const paths = seal.ext.getTemplateConfig(ext, key).filter((x) => x);
    const pathMap = paths.reduce((acc, line) => {
      const trimmed = line.trim();
      if (!trimmed) return acc;
      try {
        const eq2 = trimmed.indexOf("=");
        let id = trimmed;
        let path = trimmed;
        if (eq2 > 0) {
          id = trimmed.slice(0, eq2).trim();
          path = trimmed.slice(eq2 + 1).trim();
        } else {
          id = (trimmed.split("/").pop() || "").replace(/\.[^/.]+$/, "");
        }
        if (!id || !path) throw new Error(`本地路径格式错误:${line}`);
        acc[id] = path;
      } catch (e) {
        Logger.error(`本地路径格式错误:${line}，错误信息:${e instanceof Error ? e.message : String(e)}`);
      }
      return acc;
    }, {});
    return pathMap;
  }
