      if (memberInfo2.role === "admin" && memberInfo.role !== "owner") return `你无法禁言管理员，因为你不是群主`;
      await setGroupBan(epId, gid.replace(/^.+:/, ""), ui.userId.replace(/^.+:/, ""), duration);
      return `已禁言<${name}> ${duration}秒`;
