  // src/tool/tools/resource/tool_music.ts
  function getMusicConfig(platform) {
    const list = config_default.tool.MUSIC || [];
    for (const line of list) {
      try {
        const j2 = JSON.parse(line || "");
        if (!j2 || typeof j2 !== "object") continue;
        if (String(j2.platform || "").trim() !== platform) continue;
        const api = String(j2.api || "").trim();
        if (!api) continue;
        return { api, cookie: String(j2.cookie || "").trim() };
      } catch (e) {
        logger.error(`音乐服务配置解析失败（仅支持 JSON 格式）: ${e instanceof Error ? e.message : String(e)}，内容: ${line}`);
      }
    }
    return null;
  }
  function registerMusicPlay() {
    const tool = new Tool({
      type: "function",
      function: {
        name: "music_play",
        description: `搜索并播放音乐`,
        parameters: {
          type: "object",
          properties: {
            platform: {
              type: "string",
              description: "音乐平台",
              enum: ["网易云", "qq"]
            },
            song_name: {
              type: "string",
              description: "歌曲名称"
            }
          },
          required: ["platform", "song_name"]
        }
      }
    });
    tool.sensitive = true;
    tool.solve = async (ctx, msg, _2, args) => {
      const { platform, song_name } = args;
      if (platform !== "网易云" && platform !== "qq") {
        return `不支持的平台: ${platform}`;
      }
      const config = getMusicConfig(platform);
      if (!config) {
        return `未配置 ${platform} 的音乐服务：请在「工具」配置的「音乐服务配置」中添加 {"platform":"${platform}","api":"域名","cookie":""} 格式的 JSON 条目`;
      }
      const api = platform === "网易云" ? `${config.api}/search?keywords=${encodeURIComponent(song_name)}` : `${config.api}/search?key=${encodeURIComponent(song_name)}`;
      try {
        logger.info(`搜索音乐: ${api}`);
        const response = await fetch(api, {
          method: "GET",
          headers: {
            "Content-Type": "application/json"
          }
        });
        if (!response.ok) {
          throw new Error(`${platform}API失效`);
        }
        const data = await response.json();
        switch (platform) {
          case "网易云": {
            const song = data.result.songs[0];
            if (!song) {
              return "网易云没找到这首歌";
            }
            const id = song.id;
            const name = song.name;
            const artist = song.artists[0].name;
            const imgResponse = await fetch(`${config.api}/song/detail?ids=${id}`);
            const imgData = await imgResponse.json();
            const img = imgData.songs[0].al.picUrl;
            const headers = {
              "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36"
            };
            if (config.cookie) headers["Cookie"] = config.cookie;
            const downloadResponse = await fetch(`${config.api}/song/download/url?id=${id}`, { headers });
            const downloadData = await downloadResponse.json();
            const url = downloadData.data.url;
            seal.replyToSender(ctx, msg, `[CQ:music,type=163,url=${url},audio=${url},title=${name},content=${artist},image=${img}]`);
            return `发送成功，歌名:${name}，歌手:${artist}`;
          }
          case "qq": {
            const song = data.data.list[0];
            if (!song) {
              return "QQ音乐没找到这首歌...";
            }
            seal.replyToSender(ctx, msg, `[CQ:music,type=qq,id=${song.songid}]`);
            return "发送成功";
          }
          default: {
            return "不支持的平台";
          }
        }
      } catch (error) {
        logger.warning(`音乐搜索请求错误: ${error}`);
        return `音乐搜索请求错误: ${error}`;
      }
    };
  }

  // src/tool/tools/resource/tool_resource.ts
  function buildPathMap(items, key) {
    const pathMap = {};
    for (const item of items || []) {
      const id = item[key];
      if (id && item.path) pathMap[id] = item.path;
    }
    return pathMap;
  }
  function registerResourceTool(name, desc, key, segmentType) {
    const tool = new Tool({
      type: "function",
      function: {
        name,
        description: `${desc}。可传 name（已登记资源，资源名以调用时的报错提示为准）或 path（本地绝对路径，或相对海豹 data 目录的路径）`,
        parameters: {
          type: "object",
          properties: {
            name: {
              type: "string",
              description: "资源名称（已登记资源）"
            },
            path: {
              type: "string",
              description: "文件路径：本地绝对路径，或相对海豹 data 目录的路径"
            }
          },
          required: []
        }
      }
    });
    tool.sensitive = true;
    tool.solve = async (ctx, _2, __, args) => {
      const { name: name2, path } = args;
      const items = key === "fileId" ? config_default.resource.LOCAL_FILES || [] : config_default.resource.LOCAL_VIDEOS || [];
      const pathMap = buildPathMap(items, key);
      const nameList = Object.keys(pathMap);
      let filePath = "";
      if (name2 && path) {
        return `name 与 path 不能同时提供，请二选一：name（已登记资源）或 path（直接传路径）`;
      }
      if (name2) {
        if (!Object.prototype.hasOwnProperty.call(pathMap, name2)) {
          logger.error(`${desc}${name2}不存在`);
          return `${desc}${name2}不存在${nameList.length !== 0 ? `，可发送的资源名有:${nameList.join("、")}` : ""}`;
        }
        filePath = resolveLocalPath(pathMap[name2]);
      } else if (path) {
        filePath = resolveLocalPath(path);
      } else {
        return `必须提供 name（已登记资源）或 path（直接传路径）中的一项`;
      }
      if (!netExists()) return `未找到ob11网络连接依赖，请提示用户安装`;
      const epId = ctx.endPoint.userId;
      const segment = { type: segmentType, data: { file: filePath } };
      let result = null;
      if (ctx.isPrivate) {
        result = await sendPrivateMsg(epId, ctx.player.userId.replace(/^.+:/, ""), [segment]);
      } else {
        result = await sendGroupMsg(epId, ctx.group.groupId.replace(/^.+:/, ""), [segment]);
      }
      if (result === null || result === void 0) return `${desc}发送失败，请查看ob11网络连接依赖日志`;
      return `${desc}发送成功`;
    };
  }
  function registerResourceTools() {
    registerResourceTool("send_file", "发送本地文件", "fileId", "file");
    registerResourceTool("send_video", "发送本地视频", "videoId", "video");
  }

