  function registerAttrSeal() {
    const toolGet = new Tool({
      type: "function",
      function: {
        name: "attr_get",
        description: "获取指定玩家的指定属性",
        parameters: {
          type: "object",
          properties: {
            name: {
              type: "string",
              description: "用户名称或纯数字QQ号"
            },
            attr: {
              type: "string",
              description: "属性名称"
            }
          },
          required: ["name", "attr"]
        }
      }
    });
    toolGet.solve = async (ctx, _2, session, args) => {
      const { name, attr } = args;
      const ui = await session.context.findUser(ctx, name);
      if (ui === null) return `未找到<${name}>`;
      ({ ctx } = getCtxAndMsg(ctx.endPoint.userId, ui.userId, ctx.group.groupId));
      const value = seal.vars.intGet(ctx, attr)[0];
      return `${attr}: ${value}`;
    };
    const toolSet = new Tool({
      type: "function",
      function: {
        name: "attr_set",
        description: "修改指定玩家的指定属性",
        parameters: {
          type: "object",
          properties: {
            name: {
              type: "string",
              description: "用户名称或纯数字QQ号"
            },
            expression: {
              type: "string",
              description: "修改表达式，例如`hp=hp+1d6`就是将hp的值修改为hp+1d6"
            }
          },
          required: ["name", "expression"]
        }
      }
    });
    toolSet.solve = async (ctx, msg, session, args) => {
      const { name, expression } = args;
      const ui = await session.context.findUser(ctx, name);
      if (ui === null) return `未找到<${name}>`;
      ({ ctx, msg } = getCtxAndMsg(ctx.endPoint.userId, ui.userId, ctx.group.groupId));
      const [attr, expr] = expression.split("=");
      if (expr === void 0) return `修改失败，表达式 ${expression} 格式错误`;
      const value = seal.vars.intGet(ctx, attr)[0];
      const attrs = expr.split(/[\s\dDd+\-*/=]+/).filter((item) => item);
      const values2 = attrs.map((item) => seal.vars.intGet(ctx, item)[0]);
      let s2 = expr;
      attrs.forEach((a, i) => s2 = s2.replace(a, values2[i].toString()));
      const result = parseInt(seal.format(ctx, `{${s2}}`));
      if (isNaN(result)) return `修改失败，表达式 ${expression} 格式化错误`;
      seal.vars.intSet(ctx, attr, result);
      seal.replyToSender(ctx, msg, `进行了 ${expression} 修改
${attr}: ${value}=>${result}`);
      return `进行了 ${expression} 修改
${attr}: ${value}=>${result}`;
    };
  }

