  // src/cmd/sub_cmd/block.ts
  function registerCmdBlock() {
    const cmd = new SubCmd("block");
    cmd.desc = "黑名单相关操作";
    cmd.help = `帮助:
【.ai block add <统一ID/@xxx> <原因>】添加黑名单
【.ai block rm <统一ID/@xxx>】移除黑名单
【.ai block list】查看黑名单列表

被拉黑的对象无法触发AI对话`;
    cmd.priv = {
      priv: M2,
      args: {
        add: { priv: M2 },
        remove: { priv: M2 },
        list: { priv: M2 },
        help: { priv: U }
      }
    };
    cmd.solve = (scc) => {
      const { ctx, msg, cmdArgs, epId, ret } = scc;
      const mctx = seal.getCtxProxyFirst(ctx, cmdArgs);
      const muid = cmdArgs.amIBeMentionedFirst ? epId : mctx.player.userId;
      const val2 = cmdArgs.getArgN(2);
      switch (aliasToCmd(val2)) {
        case "add": {
          let targetId = "";
          let reason = "";
          const arg3 = cmdArgs.getArgN(3);
          const arg4 = cmdArgs.getArgN(4);
          if (cmdArgs.at.length > 0) {
            targetId = muid;
            reason = cmdArgs.getRestArgsFrom(3).trim();
          } else if (arg3 && (arg3.startsWith("QQ:") || arg3.startsWith("QQ-Group:"))) {
            targetId = arg3;
            reason = arg4;
          } else {
            seal.replyToSender(ctx, msg, "参数缺失，【.ai block add <统一ID/@xxx> <原因>】添加黑名单");
            return ret;
          }
          if (!reason || reason.trim() === "") {
            reason = "未填写原因";
          }
          if (BlockManager.checkBlock(targetId)) {
            seal.replyToSender(ctx, msg, "已经在黑名单中");
            return ret;
          }
          BlockManager.addBlock(targetId, reason);
          seal.replyToSender(ctx, msg, `已将<${targetId}>加入黑名单，原因: ${reason}`);
          return ret;
        }
        case "remove": {
          let targetId = "";
          const arg3 = cmdArgs.getArgN(3);
          if (cmdArgs.at.length > 0) {
            targetId = muid;
          } else if (arg3 && (arg3.startsWith("QQ:") || arg3.startsWith("QQ-Group:"))) {
            targetId = arg3;
          } else {
            seal.replyToSender(ctx, msg, "参数缺失，【.ai block rm <统一ID/@xxx>】移除黑名单");
            return ret;
          }
          if (BlockManager.removeBlock(targetId)) {
            seal.replyToSender(ctx, msg, `已将<${targetId}>移出黑名单`);
          } else {
            seal.replyToSender(ctx, msg, "不在黑名单中");
          }
          return ret;
        }
        case "list": {
          seal.replyToSender(ctx, msg, BlockManager.getListText());
          return ret;
        }
        default: {
          seal.replyToSender(ctx, msg, `帮助:
【.ai block add <统一ID/@xxx> <原因>】添加黑名单
【.ai block rm <统一ID/@xxx>】移除黑名单
【.ai block list】查看黑名单列表

被拉黑的对象无法触发AI对话`);
          return ret;
        }
      }
    };
  }

  // src/cmd/sub_cmd/ctxn.ts
  function registerCmdCtxn() {
    const cmd = new SubCmd("ctxn");
    cmd.desc = "上下文里的名字相关";
    cmd.help = `帮助:
【.ai ctxn status】查看上下文里的名字和自动修改状态
【.ai ctxn set [nick/card]】设置上下文里的名字为昵称/群名片
【.ai ctxn mod <数字>】自动修改上下文里的名字(只在第一次出现时修改)
0: 不自动修改
1: 自动修改为昵称
2: 自动修改为群名片`;
    cmd.priv = {
      priv: U,
      args: {
        status: { priv: U },
        set: { priv: I2 },
        mod: { priv: I2 }
      }
    };
    cmd.solve = (scc) => {
      const { ctx, msg, cmdArgs, epId, gid, session, ret } = scc;
      const val2 = cmdArgs.getArgN(2);
      switch (aliasToCmd(val2)) {
        case "status": {
          seal.replyToSender(ctx, msg, `自动修改上下文里的名字状态：${session.context.autoNameMod}
上下文里的名字有：
${session.context.userInfoList.map((ui) => `${ui.name}(${ui.id})`).join("\n")}`);
          return ret;
        }
        case "set": {
          const val3 = cmdArgs.getArgN(3);
          const mod = aliasToCmd(val3);
          if (mod !== "nickname" && mod !== "card") {
            seal.replyToSender(ctx, msg, `帮助:
【.ai ctxn set [nick/card]】设置上下文里的名字为昵称/群名片`);
            return ret;
          }
          const promises = session.context.userInfoList.map((ui) => session.context.setName(epId, gid, ui.id, mod));
          Promise.all(promises).then(() => {
            seal.replyToSender(ctx, msg, `设置完成，上下文里的名字有：
${session.context.userInfoList.map((uni) => `${uni.name}(${uni.id})`).join("\n")}`);
          });
          return ret;
        }
        case "mod": {
          const val3 = cmdArgs.getArgN(3);
          const mod = parseInt(val3);
          if (isNaN(mod) || mod < 0 || mod > 2) {
            seal.replyToSender(ctx, msg, `帮助:
【.ai ctxn mod <数字>】自动修改上下文里的名字(只在第一次出现时修改)
0: 不自动修改
1: 自动修改为昵称
2: 自动修改为群名片`);
            return ret;
          }
          session.context.autoNameMod = mod;
          session.save();
          const modText = mod === 0 ? "不自动修改" : mod === 1 ? "自动修改为昵称" : "自动修改为群名片";
          seal.replyToSender(ctx, msg, `设置成功，${modText}`);
          return ret;
        }
        default: {
          seal.replyToSender(ctx, msg, cmd.help);
          return ret;
        }
      }
    };
  }

